                        <p className="text-[10px] text-[#a09070] mt-1">{wordsForSite.toLocaleString()} words</p>
                      </div>
                    </div>
                    {latestPost && (
                      <div className="pt-2 border-t border-white/5 flex items-center justify-between text-[10px]">
